/**
 * The Luna v2 contract around the provider (adminImportProvider.ts): the chunks a generation plans, when a claimed chunk may
 * dispatch, the input each chunk sends (Draft v2 values without keys, IDs or visibility, the five v1 tag fields and the applied
 * MusicBrainz release as labelled untrusted context) and how validated output becomes stored suggestions. Pure. Owner rules:
 * docs/business-rules.md (Administrator Album Imports, Luna bullet; Administrator Metadata Lookup, Luna bullet).
 */
import { createHash } from 'node:crypto';
import { ADMIN_IMPORT_LIMITS, parseImportDate, type ImportDate, type ImportDraft, type ImportEmbeddedTags, type ImportIssue, type ImportManifest, type ImportSuggestion } from './adminImportContract';
import { derivedEntryKey, foldImportName, isDraftV2, type ImportArtistEntry, type ImportDraftV2, type ImportSuggestionV2 } from './adminImportDraft';
import { importDraftV2FromV1 } from './adminImportDraftCompat';
import { analysisContext, type AnalysisInput, type AnalysisSuggestion, type LunaArtistValue, type LunaBaseline, type LunaLookupContext, type LunaRelease } from './adminImportProvider';
import type { ImportIdentityProposals } from './adminImportIdentity';
import type { AdminImportDocument } from './adminImportService';
import { lookupCandidateSource } from '../lookup/lookupContract';
import { isPlaceholderCredit } from '../lookup/lookupIdentifiers';
import type { LookupApplication, StoredLookupCandidate } from '../lookup/metadataLookupRecord';

/** Suggestions one generation may store, adopt or tick: four Album values and three per file (title, Disc and Track Number). */
export const LUNA_SUGGESTION_LIMIT = 4 + 3 * ADMIN_IMPORT_LIMITS.files;
/** One provider call of a generation: the Album chunk, then one chunk per ten files. An `inflight` chunk is never dispatched again. */
export type AnalysisChunk = { index: number; slots: string[]; album: boolean; hash: string; state: 'pending' | 'inflight' | 'complete' | 'failed' | 'unknown'; attemptId: string | null; startedAt: Date | null; completedAt: Date | null };
/** The applied release captured at analyze admission for the whole generation (`analysis.lookupContext`), never projected. */
export type StoredLunaLookupContext = { releaseId: string; candidateKey: string; run: number; context: LunaLookupContext };
/** What a stored suggestion records of the context its chunk sent: the release, a digest of the JSON sent and whether it was cut. */
export type LunaContextRecord = { source: 'musicbrainz'; releaseId: string; digest: string; truncated: boolean };
type TaggedSlot = { slotId: string; tags: ImportEmbeddedTags };

const sha256 = (value: unknown) => createHash('sha256').update(JSON.stringify(value)).digest('hex');
const bytes = (value: unknown) => Buffer.byteLength(JSON.stringify(value));
const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const list = (value: unknown): unknown[] => Array.isArray(value) ? value : [];

/** The chunks of a generation; each hash is importDigest({generation, manifest, baseline, tags, slots, album}), as always. */
export function lunaAnalysisChunks(generation: number, manifest: ImportManifest, baseline: unknown, tags: readonly TaggedSlot[]): AnalysisChunk[] {
    const chunks: AnalysisChunk[] = [];
    const add = (slots: string[], album: boolean) => chunks.push({ index: chunks.length, slots, album, hash: sha256({ generation, manifest, baseline, tags, slots, album }), state: 'pending', attemptId: null, startedAt: null, completedAt: null });
    add([], true);
    for (let offset = 0; offset < manifest.files.length; offset += ADMIN_IMPORT_LIMITS.tracksPerChunk) add(manifest.files.slice(offset, offset + ADMIN_IMPORT_LIMITS.tracksPerChunk).map(file => file.slotId), false);
    return chunks;
}

/**
 * Why a claimed analysis may not dispatch: a chunk left in flight is an unknown paid outcome that is never replayed, an expired or
 * missing grant has lapsed, and the project's attempts are spent; null when it may (the actor and daily checks follow).
 */
export function lunaDispatchIssue(analysis: { chunks: readonly { state: string }[]; grantExpiresAt: Date | null }, attemptsUsed: number, now: Date): ImportIssue {
    if (analysis.chunks.some(chunk => chunk.state === 'inflight')) return 'providerOutcomeUnknown';
    if (!analysis.grantExpiresAt || analysis.grantExpiresAt <= now) return 'grantExpired';
    return attemptsUsed >= ADMIN_IMPORT_LIMITS.attempts ? 'budgetExhausted' : null;
}

/** The Draft v2 values Luna reads: names, roles and join phrases of entries, the label's name; tracks only of `slots` (none for the Album chunk). */
export function lunaBaseline(draft: ImportDraftV2, slots: readonly string[], album: boolean): LunaBaseline {
    return {
        album: { title: draft.album.title, artists: draft.album.artists.map(({ name, role, joinPhrase }) => ({ name, role, joinPhrase })), label: draft.album.label?.name ?? null,
            releaseDate: draft.album.releaseDate ? { ...draft.album.releaseDate } : null },
        tracks: album ? [] : draft.tracks.filter(track => slots.includes(track.slotId)).map(({ slotId, title, discNumber, trackNumber }) => ({ slotId, title, discNumber, trackNumber }))
    };
}

/** Embedded tags are secondary untrusted evidence with a separate prompt-size allowance of 12 KB per chunk. */
export function boundedLunaTags(tags: readonly TaggedSlot[], slots: readonly string[]): TaggedSlot[] {
    let used = 0;
    return tags.filter(item => slots.includes(item.slotId)).filter(item => { used += bytes(item); return used <= 12_000; });
}

const text = (value: unknown, max: number) => typeof value === 'string' && value.length <= max ? value : null;
const position = (value: unknown) => Number.isSafeInteger(value) && (value as number) >= 0 ? value as number : null;
const date = (value: unknown): ImportDate | null => { try { return value === null || value === undefined ? null : parseImportDate(value); } catch { return null; } };
/** The allowlisted values of a stored release, read defensively; never an identifier, barcode, catalogue number, ISRC or artwork flag. */
function lunaRelease(raw: Record<string, unknown>): LunaRelease | null {
    const title = text(raw.title, 500); if (title === null) return null;
    const artistCredit = list(raw.artistCredit).filter(isRecord).flatMap(credit => { const name = text(credit.name, 500); return name ? [{ name, joinPhrase: text(credit.joinPhrase, 100) ?? '' }] : []; });
    const labels = [...new Set(list(raw.labels).filter(isRecord).map(label => text(label.name, 500)).filter((name): name is string => Boolean(name)))];
    const media = list(raw.media).filter(isRecord).flatMap(medium => {
        const at = position(medium.position); if (at === null) return [];
        const tracks = list(medium.tracks).filter(isRecord).flatMap(track => {
            const index = position(track.position), name = text(track.title, 500);
            return index === null || name === null ? [] : [{ position: index, number: text(track.number, 50) ?? '', title: name, lengthMs: position(track.lengthMs) }];
        }).sort((left, right) => left.position - right.position);
        return [{ position: at, format: text(medium.format, 100), tracks }];
    }).sort((left, right) => left.position - right.position);
    return { title, artistCredit, labels, date: date(raw.date), firstReleaseDate: date(raw.groupFirstReleaseDate), media };
}

/**
 * The context of the release applied to an import: only a preselected or chosen MusicBrainz candidate whose stored details were
 * fetched for that same release, reduced to its allowlisted values and fitted to the whole input allowance; null without one.
 * Other candidates and any iTunes evidence are never read here.
 */
export function lunaLookupContextFor(found: { applied: Pick<LookupApplication, 'run' | 'candidateKey' | 'releaseId' | 'choice'>; candidate: StoredLookupCandidate } | null): StoredLunaLookupContext | null {
    if (!found || !isRecord(found.applied) || !isRecord(found.candidate)) return null;
    const applied = found.applied as Record<string, unknown>, candidate = found.candidate as Record<string, unknown>;
    // An iTunes-only candidate (by its key, whatever its stored source says) is never Luna context.
    if ((applied.choice !== 'preselected' && applied.choice !== 'chosen') || lookupCandidateSource(applied.candidateKey) !== 'musicbrainz' || typeof applied.releaseId !== 'string'
        || !Number.isSafeInteger(applied.run)) return null;
    if (candidate.key !== applied.candidateKey || candidate.source !== 'musicbrainz' || candidate.releaseId !== applied.releaseId || candidate.details !== 'fetched' || !isRecord(candidate.release)) return null;
    const release = lunaRelease(candidate.release); if (!release) return null;
    const context = fitLunaLookupContext({ source: 'musicbrainz', kind: 'appliedRelease', trust: 'untrusted', truncated: false, release }, ADMIN_IMPORT_LIMITS.inputBytes);
    return context && { releaseId: applied.releaseId, candidateKey: applied.candidateKey as string, run: applied.run as number, context };
}

/**
 * Deterministic fit of a context into `maxBytes` of JSON: the whole context when it fits, else the longest prefix of its tracks in
 * medium and position order (media without a kept track left out) marked `truncated`, else null when even no track does not fit.
 */
export function fitLunaLookupContext(context: LunaLookupContext, maxBytes: number): LunaLookupContext | null {
    if (bytes(context) <= maxBytes) return context;
    const total = context.release.media.reduce((sum, medium) => sum + medium.tracks.length, 0);
    const prefix = (count: number): LunaLookupContext => {
        const media: LunaRelease['media'] = []; let left = count;
        for (const medium of context.release.media) { if (left <= 0) break; const tracks = medium.tracks.slice(0, left); left -= tracks.length; if (tracks.length) media.push({ ...medium, tracks }); }
        return { ...context, truncated: true, release: { ...context.release, media } };
    };
    if (bytes(prefix(0)) > maxBytes) return null;
    let low = 0, high = total;
    while (low < high) { const middle = Math.ceil((low + high) / 2); if (bytes(prefix(middle)) <= maxBytes) low = middle; else high = middle - 1; }
    return prefix(low);
}

/** The Draft v2 form of a stored analysis baseline; a v1 baseline (an analysis queued before Draft v2) converts. */
const storedBaseline = (doc: Pick<AdminImportDocument, '_id' | 'analysis' | 'draft'>): ImportDraftV2 => {
    const stored = doc.analysis.baseline ?? doc.draft;
    return isDraftV2(stored) ? stored : importDraftV2FromV1(stored as ImportDraft, doc._id.toHexString());
};
/**
 * One chunk's provider input: the manifest (all files for the Album chunk, else the chunk's), the stored baseline as Luna reads it,
 * the bounded tags and the generation's applied-release context (an import's or a review's) fitted so the whole input stays within
 * ADMIN_IMPORT_LIMITS.inputBytes (it replaces the `null` the size is measured with).
 */
export function lunaAnalysisInput(doc: Pick<AdminImportDocument, '_id' | 'purpose' | 'manifest' | 'analysis' | 'draft'>, chunk: AnalysisChunk): AnalysisInput {
    const { analysis, manifest } = doc;
    const input: AnalysisInput = { ...(doc.purpose === 'catalogReview' ? { purpose: 'catalogReview' as const } : {}), generation: analysis.generation, chunk: chunk.index,
        manifest: { rootLabel: manifest.rootLabel, files: chunk.album ? manifest.files : manifest.files.filter(file => chunk.slots.includes(file.slotId)) },
        baseline: lunaBaseline(storedBaseline(doc), chunk.slots, chunk.album), slots: chunk.slots, album: chunk.album,
        tags: boundedLunaTags(analysis.tags ?? [], chunk.album ? manifest.files.slice(0, ADMIN_IMPORT_LIMITS.tracksPerChunk).map(file => file.slotId) : chunk.slots), lookupContext: null };
    const stored = analysis.lookupContext?.context;
    if (!stored) return input;
    return { ...input, lookupContext: fitLunaLookupContext(stored, ADMIN_IMPORT_LIMITS.inputBytes - bytes(analysisContext(input)) + bytes(null)) };
}

/** What each suggestion of a chunk records of the context it sent; null when it sent none. */
export function lunaContextRecord(stored: StoredLunaLookupContext | null | undefined, sent: LunaLookupContext | null): LunaContextRecord | null {
    return stored && sent ? { source: 'musicbrainz', releaseId: stored.releaseId, digest: sha256(sent), truncated: sent.truncated } : null;
}

/**
 * One validated Luna value as a Draft v2 suggestion against `baseline` (the analysis baseline). An Artist entry whose folded name
 * equals a baseline entry's takes that entry's key and MusicBrainz ID, so an unchanged entry's decisions survive exactly as
 * retainBoundDecisions keeps them and a case-only correction keeps the ID, as the Draft v2 rename rule does (acceptance verifies the
 * folded name again); any other entry gets a key derived from `seed` and no ID. A label never carries an ID. Null drops the value: a
 * placeholder Artist entry or label (imports never suggest a stand-in), an unknown slot, or a Disc Number for a slot outside
 * `discSlots` (a catalog review's tracks whose source captured one; null means every slot).
 */
export function lunaSuggestionV2(raw: AnalysisSuggestion, baseline: ImportDraftV2, seed: { importId: string; suggestionId: string }, discSlots: ReadonlySet<string> | null): Omit<ImportSuggestionV2, 'id' | 'generation' | 'decision'> | null {
    const { scope, slotId, source, evidence } = raw;
    if (scope === 'album') {
        if (raw.field === 'title' || raw.field === 'releaseDate') return { scope, slotId: null, field: raw.field, baseline: structuredClone(baseline.album[raw.field]), value: raw.value as string | ImportDate, source, evidence };
        if (raw.field === 'label') {
            const name = raw.value as string; if (isPlaceholderCredit(name)) return null;
            return { scope, slotId: null, field: 'label', baseline: structuredClone(baseline.album.label), value: { name, musicBrainzId: null }, source, evidence };
        }
        if (raw.field !== 'artists') return null;
        const entries = raw.value as LunaArtistValue[]; if (entries.some(entry => isPlaceholderCredit(entry.name))) return null;
        const value = entries.map(({ name, role, joinPhrase }, index): ImportArtistEntry => {
            const same = baseline.album.artists.find(entry => foldImportName(entry.name) === foldImportName(name));
            return { key: same?.key ?? derivedEntryKey({ ...seed, index }), name, role, joinPhrase, musicBrainzId: same?.musicBrainzId ?? null };
        });
        return { scope, slotId: null, field: 'artists', baseline: structuredClone(baseline.album.artists), value, source, evidence };
    }
    const track = baseline.tracks.find(item => item.slotId === slotId);
    if (!track || (raw.field !== 'title' && raw.field !== 'discNumber' && raw.field !== 'trackNumber') || (raw.field === 'discNumber' && discSlots && !discSlots.has(track.slotId))) return null;
    return { scope, slotId: track.slotId, field: raw.field, baseline: track[raw.field], value: raw.value as string | number, source, evidence };
}

/**
 * A Luna value for a format-1 project whose analysis an earlier release queued: a single primary entry without a join phrase
 * becomes `artistName`; labels, Disc Numbers, several entries and placeholders are dropped (null). The project stays format 1.
 */
export function lunaSuggestionV1(raw: AnalysisSuggestion, baseline: ImportDraft): Omit<ImportSuggestion, 'id' | 'generation' | 'decision'> | null {
    const { scope, slotId, source, evidence } = raw;
    if (scope === 'album') {
        if (raw.field === 'title' || raw.field === 'releaseDate') return { scope, slotId: null, field: raw.field, baseline: structuredClone(baseline.album[raw.field]), value: raw.value as string | ImportDate, source, evidence };
        if (raw.field !== 'artists') return null;
        const entries = raw.value as LunaArtistValue[], [only] = entries;
        if (entries.length !== 1 || only.role !== 'primary' || only.joinPhrase !== null || isPlaceholderCredit(only.name)) return null;
        return { scope, slotId: null, field: 'artistName', baseline: baseline.album.artistName, value: only.name, source, evidence };
    }
    const track = baseline.tracks.find(item => item.slotId === slotId);
    if (!track || (raw.field !== 'title' && raw.field !== 'trackNumber')) return null;
    return { scope, slotId: track.slotId, field: raw.field, baseline: track[raw.field], value: raw.value as string | number, source, evidence };
}

/** The values pending Luna proposals would write on identity paths, for which the confirmation's candidate read also looks. */
export function lunaIdentityProposals(suggestions: readonly ImportSuggestionV2[]): ImportIdentityProposals {
    const proposals = { artistNames: [] as string[], labelNames: [] as string[], albumTitles: [] as string[], trackTitles: [] as { slotId: string; title: string }[] };
    for (const suggestion of suggestions) {
        const { scope, field, value } = suggestion;
        if (suggestion.decision !== 'pending') continue;
        if (scope === 'album' && field === 'artists' && Array.isArray(value)) proposals.artistNames.push(...value.map(entry => entry.name));
        else if (scope === 'album' && field === 'label' && isRecord(value) && typeof (value as { name?: unknown }).name === 'string') proposals.labelNames.push((value as { name: string }).name);
        else if (scope === 'album' && field === 'title' && typeof value === 'string' && value) proposals.albumTitles.push(value);
        else if (scope === 'track' && field === 'title' && typeof value === 'string' && value && suggestion.slotId) proposals.trackTitles.push({ slotId: suggestion.slotId, title: value });
    }
    return proposals;
}
